// ---------- Pack the Rucksack ----------
private Button[] cards = new Button[12];   // the 12 kit cards
private bool checkedYet = false;           // true after Check

private void frmRucksack_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    picPackIcon.Image = Files.Picture("Icons", "icon-rucksack-64.png");
    List<KitItem> pack = new List<KitItem>();
    List<KitItem> leave = new List<KitItem>();
    foreach (KitItem item in KitItem.LoadAll())
    {
        if (item.Pack) pack.Add(item);
        else leave.Add(item);
    }
    if (pack.Count < 6 || leave.Count < 6)
    {
        lblLeft.Text = "Pack the Rucksack needs 6 items to pack and "
            + "6 to leave in Data\\kit.txt.";
        return;
    }
    DealCards(pack, leave);
}

// Picks 6 to pack and 6 to leave at random, then mixes all 12
private void DealCards(List<KitItem> pack, List<KitItem> leave)
{
    KitItem[] chosen = new KitItem[12];
    int[] packOrder = Mix.ShuffledNumbers(pack.Count);
    int[] leaveOrder = Mix.ShuffledNumbers(leave.Count);
    for (int i = 0; i < 6; i++)
    {
        chosen[i] = pack[packOrder[i]];
        chosen[i + 6] = leave[leaveOrder[i]];
    }
    int[] order = Mix.ShuffledNumbers(12);
    for (int i = 0; i < 12; i++)
    {
        cards[i] = MakeCard(chosen[order[i]]);
        flpPile.Controls.Add(cards[i]);
    }
    ShowLeft();
}

// One kit card: the picture above the name, the KitItem in its Tag
private Button MakeCard(KitItem item)
{
    Button card = new Button();
    card.Size = new Size(96, 104);
    card.Margin = new Padding(4, 2, 4, 2);
    card.FlatStyle = FlatStyle.Flat;
    card.BackColor = Color.FromArgb(243, 245, 242);
    card.Font = new Font("Segoe UI", 9);
    // The pictures are 128 pixels; 64 leaves room for the name
    Image picture = Files.Picture("Kit", item.Picture);
    if (picture != null) card.Image = new Bitmap(picture, 64, 64);
    card.Text = item.Name;
    card.TextImageRelation = TextImageRelation.ImageAboveText;
    card.Cursor = Cursors.Hand;
    return card;
}

// Pressing on a card picks it up
private void Card_MouseDown(object sender, MouseEventArgs e)
{
    if (checkedYet) return;        // no more moving after Check
    Button card = (Button)sender;
    card.DoDragDrop(card, DragDropEffects.Move);
}

// A card held over a zone shows the move cursor
private void Zone_DragEnter(object sender, DragEventArgs e)
{
    e.Effect = DragDropEffects.Move;
}

// A card let go over a zone moves into that zone
private void Zone_DragDrop(object sender, DragEventArgs e)
{
    Button card = (Button)e.Data.GetData(typeof(Button));
    if (card == null) return;
    FlowLayoutPanel zone = ZoneOf((Control)sender);
    zone.Controls.Add(card);       // moves the card out of its old zone
    Sound.Play("drop.wav");
    ShowLeft();
}

// The zone a drop belongs to: a heading, a card or the zone itself
private FlowLayoutPanel ZoneOf(Control target)
{
    if (target.Tag is FlowLayoutPanel)
    {
        return (FlowLayoutPanel)target.Tag;    // a heading
    }
    if (target is Button) return (FlowLayoutPanel)target.Parent;
    return (FlowLayoutPanel)target;
}

// How many cards are still on the pile
private void ShowLeft()
{
    int left = flpPile.Controls.Count;
    lblLeft.Text = "Items left to sort: " + left;
}

private void frmRucksack_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    picPackIcon.Image = Files.Picture("Icons", "icon-rucksack-64.png");
    // A heading's Tag is its drop zone, so a drop on it still counts
    lblPileHead.Tag = flpPile;
    picPackIcon.Tag = flpPack;
    lblPackHead.Tag = flpPack;
    lblLeaveHead.Tag = flpLeave;
    List<KitItem> pack = new List<KitItem>();
    List<KitItem> leave = new List<KitItem>();
    foreach (KitItem item in KitItem.LoadAll())
    {
        if (item.Pack) pack.Add(item);
        else leave.Add(item);
    }
    if (pack.Count < 6 || leave.Count < 6)
    {
        lblLeft.Text = "Pack the Rucksack needs 6 items to pack and "
            + "6 to leave in Data\\kit.txt.";
        return;
    }
    DealCards(pack, leave);
}

// One kit card: the picture above the name, the KitItem in its Tag
private Button MakeCard(KitItem item)
{
    Button card = new Button();
    card.Size = new Size(96, 104);
    card.Margin = new Padding(4, 2, 4, 2);
    card.FlatStyle = FlatStyle.Flat;
    card.BackColor = Color.FromArgb(243, 245, 242);
    card.Font = new Font("Segoe UI", 9);
    // The pictures are 128 pixels; 64 leaves room for the name
    Image picture = Files.Picture("Kit", item.Picture);
    if (picture != null) card.Image = new Bitmap(picture, 64, 64);
    card.Text = item.Name;
    card.TextImageRelation = TextImageRelation.ImageAboveText;
    card.Cursor = Cursors.Hand;
    card.Tag = item;
    card.AllowDrop = true;         // a drop on a card lands in its zone
    card.MouseDown += Card_MouseDown;
    card.Click += Card_Click;
    card.DragEnter += Zone_DragEnter;
    card.DragDrop += Zone_DragDrop;
    return card;
}

// Check my rucksack, then See my score
private void btnCheck_Click(object sender, EventArgs e)
{
    if (checkedYet)
    {
        ShowRoundOver();
        return;
    }
    int left = flpPile.Controls.Count;
    if (left > 0)
    {
        lblLeft.Text = "Sort every item first. Items left to sort: "
            + left;
        return;
    }
    checkedYet = true;
    btnCheck.Text = "See my score";
}

// Check my rucksack, then See my score
private void btnCheck_Click(object sender, EventArgs e)
{
    if (checkedYet)
    {
        ShowRoundOver();
        return;
    }
    int left = flpPile.Controls.Count;
    if (left > 0)
    {
        lblLeft.Text = "Sort every item first. Items left to sort: "
            + left;
        return;
    }
    checkedYet = true;
    int right = 0;
    foreach (Button card in cards)
    {
        if (InRightPlace(card)) right++;
        MarkCard(card);
    }
    lblLeft.Text = right + " of 12 in the right place.";
    lblPileHead.Text = "Why?";
    lblReason.Text = "Click any item to see why it belongs where it "
        + "does.";
    lblReason.Visible = true;
    if (right >= 9) Sound.Play("correct.wav");
    else Sound.Play("wrong.wav");
    RecordResult(right);
    btnCheck.Text = "See my score";
}

// True when the card is in the zone it belongs in
private bool InRightPlace(Button card)
{
    KitItem item = (KitItem)card.Tag;
    bool packed = card.Parent == flpPack;
    return packed == item.Pack;
}

// Moss with a tick for the right place, bracken with a cross if not
private void MarkCard(Button card)
{
    PictureBox mark = new PictureBox();
    mark.Size = new Size(22, 22);
    mark.Location = new Point(70, 4);
    mark.SizeMode = PictureBoxSizeMode.Zoom;
    mark.BackColor = Color.Transparent;
    if (InRightPlace(card))
    {
        card.BackColor = Color.FromArgb(227, 241, 228);
        mark.Image = Files.Picture("Icons", "icon-check-64.png");
    }
    else
    {
        card.BackColor = Color.FromArgb(248, 225, 222);
        mark.Image = Files.Picture("Icons", "icon-cross-64.png");
    }
    card.Controls.Add(mark);
    card.Cursor = Cursors.Default;
}

// After Check, clicking a card shows why it belongs where it does
private void Card_Click(object sender, EventArgs e)
{
    if (!checkedYet) return;
    KitItem item = (KitItem)((Button)sender).Tag;
    lblReason.Text = item.Name + ": " + item.Reason;
}

// Works out the score, adds the feedback, then keeps the result
private void RecordResult(int right)
{
    int score = right * 100 / 12;          // whole numbers: 11 is 91
    result = new GameResult("Pack the Rucksack", score);
    AddFeedback();
    KeepResult();
}

// Writes what went well and what went wrong into the result
private void AddFeedback()
{
    foreach (Button card in cards)
    {
        KitItem item = (KitItem)card.Tag;
        string name = item.Name.ToLower();
        string did = "You packed the " + name + ".";
        if (card.Parent == flpLeave)
        {
            did = "You left the " + name + " at home.";
        }
        if (InRightPlace(card)) result.WentWell.Add(did);
        else result.WentWrong.Add(did + " " + item.Reason);
    }
}

